import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the (K, K, 1) 3D convolution.
#
# Structural optimization over the previous direct/per-output-thread kernel:
# each CTA now cooperatively tiles a 16x16 spatial output block for a fixed
# (batch, group, output-depth) triple, stages the required (haloed) input
# window for that group's input channels into shared memory ONCE, and then
# reuses that shared-memory tile across ALL output channels within the
# group (looping over Cout_per_group). This removes the previous kernel's
# redundant re-fetching of the same input window from global memory once
# per output channel (a Cout_per_group-fold reduction in global loads of X),
# while preserving exact stride / padding / dilation / groups semantics.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.extern .shared .align 4 .b8 smem_buf[];

.visible .entry conv3d_hw1_kernel(
    .param .u64 p_X,
    .param .u64 p_W,
    .param .u64 p_Bias,
    .param .u64 p_Y,
    .param .u32 p_N,
    .param .u32 p_Cin,
    .param .u32 p_H,
    .param .u32 p_Win,
    .param .u32 p_D,
    .param .u32 p_Cout,
    .param .u32 p_CinPerGroup,
    .param .u32 p_CoutPerGroup,
    .param .u32 p_Kh,
    .param .u32 p_Kw,
    .param .u32 p_Stride,
    .param .u32 p_Padding,
    .param .u32 p_Dilation,
    .param .u32 p_Hout,
    .param .u32 p_Wout,
    .param .u32 p_Dout,
    .param .u32 p_Groups,
    .param .u32 p_TileHin,
    .param .u32 p_TileWin
)
{
    .reg .pred   %p<40>;
    .reg .b32    %r<100>;
    .reg .b64    %rd<90>;
    .reg .f32    %f<10>;

    ld.param.u64    %rd1, [p_X];
    ld.param.u64    %rd2, [p_W];
    ld.param.u64    %rd3, [p_Bias];
    ld.param.u64    %rd4, [p_Y];
    ld.param.u32    %r1,  [p_N];
    ld.param.u32    %r2,  [p_Cin];
    ld.param.u32    %r3,  [p_H];
    ld.param.u32    %r4,  [p_Win];
    ld.param.u32    %r5,  [p_D];
    ld.param.u32    %r6,  [p_Cout];
    ld.param.u32    %r7,  [p_CinPerGroup];
    ld.param.u32    %r8,  [p_CoutPerGroup];
    ld.param.u32    %r9,  [p_Kh];
    ld.param.u32    %r10, [p_Kw];
    ld.param.u32    %r11, [p_Stride];
    ld.param.u32    %r12, [p_Padding];
    ld.param.u32    %r13, [p_Dilation];
    ld.param.u32    %r14, [p_Hout];
    ld.param.u32    %r15, [p_Wout];
    ld.param.u32    %r16, [p_Dout];
    ld.param.u32    %r17, [p_Groups];
    ld.param.u32    %r18, [p_TileHin];
    ld.param.u32    %r19, [p_TileWin];

    cvta.to.global.u64 %rd5, %rd1;
    cvta.to.global.u64 %rd6, %rd2;
    cvta.to.global.u64 %rd7, %rd4;

    mov.u32         %r20, %tid.x;
    mov.u32         %r21, %tid.y;
    mov.u32         %r22, %ctaid.x;
    mov.u32         %r23, %ctaid.y;
    mov.u32         %r24, %ctaid.z;

    mul.lo.s32      %r25, %r22, 16;
    add.s32         %r26, %r25, %r20;   // ow
    mul.lo.s32      %r27, %r23, 16;
    add.s32         %r28, %r27, %r21;   // oh

    div.s32         %r29, %r24, %r16;   // tmp = bz / Dout
    rem.s32         %r30, %r24, %r16;   // od
    div.s32         %r31, %r29, %r17;   // n
    rem.s32         %r32, %r29, %r17;   // g

    mul.lo.s32      %r33, %r30, %r11;
    sub.s32         %r34, %r33, %r12;   // id

    mul.lo.s32      %r35, %r27, %r11;
    sub.s32         %r36, %r35, %r12;   // ih_base

    mul.lo.s32      %r37, %r25, %r11;
    sub.s32         %r38, %r37, %r12;   // iw_base

    mul.lo.s32      %r39, %r21, 16;
    add.s32         %r40, %r39, %r20;   // flat_tid

    mul.lo.s32      %r41, %r7, %r18;
    mul.lo.s32      %r42, %r41, %r19;   // total_elems
    mul.lo.s32      %r44, %r18, %r19;   // plane = TileHin*TileWin

    mov.u32         %r45, smem_buf;

    mov.u32         %r50, %r40;         // idx

LOAD_LOOP:
    setp.ge.s32     %p1, %r50, %r42;
    @%p1 bra LOAD_DONE;

    div.s32         %r51, %r50, %r44;   // c
    rem.s32         %r52, %r50, %r44;
    div.s32         %r53, %r52, %r19;   // lh
    rem.s32         %r54, %r52, %r19;   // lw

    add.s32         %r55, %r36, %r53;   // ih
    add.s32         %r56, %r38, %r54;   // iw

    mov.f32         %f1, 0f00000000;

    setp.lt.s32     %p2, %r55, 0;
    setp.ge.s32     %p3, %r55, %r3;
    or.pred         %p4, %p2, %p3;
    setp.lt.s32     %p5, %r56, 0;
    setp.ge.s32     %p6, %r56, %r4;
    or.pred         %p7, %p5, %p6;
    or.pred         %p8, %p4, %p7;
    setp.lt.s32     %p9, %r34, 0;
    setp.ge.s32     %p10, %r34, %r5;
    or.pred         %p11, %p9, %p10;
    or.pred         %p12, %p8, %p11;
    @%p12 bra STORE_SMEM;

    mul.lo.s32      %r58, %r32, %r7;
    add.s32         %r59, %r58, %r51;   // cin_global

    cvt.s64.s32     %rd10, %r31;
    cvt.s64.s32     %rd11, %r2;
    mul.lo.s64      %rd12, %rd10, %rd11;
    cvt.s64.s32     %rd13, %r59;
    add.s64         %rd14, %rd12, %rd13;
    cvt.s64.s32     %rd15, %r3;
    mul.lo.s64      %rd16, %rd14, %rd15;
    cvt.s64.s32     %rd17, %r55;
    add.s64         %rd18, %rd16, %rd17;
    cvt.s64.s32     %rd19, %r4;
    mul.lo.s64      %rd20, %rd18, %rd19;
    cvt.s64.s32     %rd21, %r56;
    add.s64         %rd22, %rd20, %rd21;
    cvt.s64.s32     %rd23, %r5;
    mul.lo.s64      %rd24, %rd22, %rd23;
    cvt.s64.s32     %rd25, %r34;
    add.s64         %rd26, %rd24, %rd25;
    mul.lo.s64      %rd27, %rd26, 4;
    add.s64         %rd28, %rd5, %rd27;
    ld.global.f32   %f1, [%rd28];

STORE_SMEM:
    mul.lo.s32      %r60, %r50, 4;
    add.s32         %r61, %r45, %r60;
    st.shared.f32   [%r61], %f1;

    add.s32         %r50, %r50, 256;
    bra.uni         LOAD_LOOP;

LOAD_DONE:
    bar.sync        0;

    setp.ge.s32     %p13, %r28, %r14;
    setp.ge.s32     %p14, %r26, %r15;
    or.pred         %p15, %p13, %p14;
    @%p15 bra KERNEL_DONE;

    mov.u32         %r70, 0;

OC_LOOP:
    setp.ge.s32     %p16, %r70, %r8;
    @%p16 bra KERNEL_DONE;

    mul.lo.s32      %r71, %r32, %r8;
    add.s32         %r72, %r71, %r70;   // oc_global

    mov.f32         %f2, 0f00000000;
    mov.u32         %r73, 0;            // c

C_LOOP:
    setp.ge.s32     %p17, %r73, %r7;
    @%p17 bra C_DONE;

    mov.u32         %r74, 0;            // kh
KH_LOOP:
    setp.ge.s32     %p18, %r74, %r9;
    @%p18 bra KH_DONE;

    mul.lo.s32      %r75, %r21, %r11;
    mul.lo.s32      %r76, %r74, %r13;
    add.s32         %r77, %r75, %r76;   // sh_h

    mov.u32         %r78, 0;            // kw
KW_LOOP:
    setp.ge.s32     %p19, %r78, %r10;
    @%p19 bra KW_DONE;

    mul.lo.s32      %r79, %r20, %r11;
    mul.lo.s32      %r80, %r78, %r13;
    add.s32         %r81, %r79, %r80;   // sh_w

    mul.lo.s32      %r82, %r73, %r44;
    mul.lo.s32      %r83, %r77, %r19;
    add.s32         %r84, %r82, %r83;
    add.s32         %r85, %r84, %r81;   // shared_idx

    mul.lo.s32      %r86, %r85, 4;
    add.s32         %r87, %r45, %r86;
    ld.shared.f32   %f3, [%r87];

    mul.lo.s32      %r88, %r72, %r7;
    add.s32         %r89, %r88, %r73;
    mul.lo.s32      %r90, %r89, %r9;
    add.s32         %r91, %r90, %r74;
    mul.lo.s32      %r92, %r91, %r10;
    add.s32         %r93, %r92, %r78;

    cvt.s64.s32     %rd30, %r93;
    mul.lo.s64      %rd31, %rd30, 4;
    add.s64         %rd32, %rd6, %rd31;
    ld.global.f32   %f4, [%rd32];

    fma.rn.f32      %f2, %f3, %f4, %f2;

    add.s32         %r78, %r78, 1;
    bra.uni         KW_LOOP;

KW_DONE:
    add.s32         %r74, %r74, 1;
    bra.uni         KH_LOOP;

KH_DONE:
    add.s32         %r73, %r73, 1;
    bra.uni         C_LOOP;

C_DONE:
    setp.eq.s64     %p20, %rd3, 0;
    @%p20 bra STORE_OUT;

    cvta.to.global.u64 %rd40, %rd3;
    cvt.s64.s32     %rd41, %r72;
    mul.lo.s64      %rd42, %rd41, 4;
    add.s64         %rd43, %rd40, %rd42;
    ld.global.f32   %f5, [%rd43];
    add.f32         %f2, %f2, %f5;

STORE_OUT:
    cvt.s64.s32     %rd50, %r31;
    cvt.s64.s32     %rd51, %r6;
    mul.lo.s64      %rd52, %rd50, %rd51;
    cvt.s64.s32     %rd53, %r72;
    add.s64         %rd54, %rd52, %rd53;
    cvt.s64.s32     %rd55, %r14;
    mul.lo.s64      %rd56, %rd54, %rd55;
    cvt.s64.s32     %rd57, %r28;
    add.s64         %rd58, %rd56, %rd57;
    cvt.s64.s32     %rd59, %r15;
    mul.lo.s64      %rd60, %rd58, %rd59;
    cvt.s64.s32     %rd61, %r26;
    add.s64         %rd62, %rd60, %rd61;
    cvt.s64.s32     %rd63, %r16;
    mul.lo.s64      %rd64, %rd62, %rd63;
    cvt.s64.s32     %rd65, %r30;
    add.s64         %rd66, %rd64, %rd65;
    mul.lo.s64      %rd67, %rd66, 4;
    add.s64         %rd68, %rd7, %rd67;
    st.global.f32   [%rd68], %f2;

    add.s32         %r70, %r70, 1;
    bra.uni         OC_LOOP;

KERNEL_DONE:
    ret;
}
"""

_KERNEL_NAME = "conv3d_hw1_kernel"
_MODULE = None

_TILE_OH = 16
_TILE_OW = 16


def _get_module() -> PtxModule:
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Sanity check that the PTX module exposes the expected entry point."""
    module = _get_module()
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"entry '{_KERNEL_NAME}' not found in PTX module"
    return True


class ModelNew(nn.Module):
    """
    3D convolution with kernel (K, K, 1), implemented via a hand-written
    PTX kernel launched through cutegen.ptx_runtime.PtxModule.

    The kernel tiles the (Hout, Wout) output plane per CTA for a fixed
    (batch, group, output-depth) triple, stages the required haloed input
    window into shared memory once per CTA, and reuses it across all output
    channels of that group (register-resident accumulation), removing the
    redundant global-memory re-reads of X that a fully direct per-output
    thread mapping would otherwise incur.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        # Weight shape matches nn.Conv3d: [Cout, Cin/groups, Kh, Kw, Kd=1]
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 is supported"

        x_c = x.contiguous()
        w_c = self.weight.squeeze(-1).contiguous()  # [Cout, Cin/groups, Kh, Kw]

        N, Cin, H, Win, D = x_c.shape
        Cout, Cin_per_group, Kh, Kw = w_c.shape
        stride = int(self.stride)
        padding = int(self.padding)
        dilation = int(self.dilation)
        groups = int(self.groups)

        assert Cin % groups == 0 and Cout % groups == 0
        assert Cin_per_group == Cin // groups
        Cout_per_group = Cout // groups

        Hout = (H + 2 * padding - dilation * (Kh - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (Kw - 1) - 1) // stride + 1
        Dout = (D + 2 * padding - 1 * (1 - 1) - 1) // stride + 1  # kernel depth == 1

        assert Hout > 0 and Wout > 0 and Dout > 0

        y = torch.empty((N, Cout, Hout, Wout, Dout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            bias_ptr = int(b_c.data_ptr())
        else:
            b_c = None
            bias_ptr = 0

        tile_h_in = (_TILE_OH - 1) * stride + (Kh - 1) * dilation + 1
        tile_w_in = (_TILE_OW - 1) * stride + (Kw - 1) * dilation + 1

        grid_x = max(1, (Wout + _TILE_OW - 1) // _TILE_OW)
        grid_y = max(1, (Hout + _TILE_OH - 1) // _TILE_OH)
        grid_z = max(1, N * groups * Dout)

        shared_mem_bytes = int(Cin_per_group * tile_h_in * tile_w_in * 4)

        module = _get_module()
        stream = torch.cuda.current_stream(device=x.device).cuda_stream

        module.launch(
            _KERNEL_NAME,
            grid=(grid_x, grid_y, grid_z),
            block=(_TILE_OW, _TILE_OH, 1),
            shared_mem=shared_mem_bytes,
            stream=stream,
            args=[
                u64(int(x_c.data_ptr())),
                u64(int(w_c.data_ptr())),
                u64(bias_ptr),
                u64(int(y.data_ptr())),
                i32(N), i32(Cin), i32(H), i32(Win), i32(D),
                i32(Cout), i32(Cin_per_group), i32(Cout_per_group),
                i32(Kh), i32(Kw),
                i32(stride), i32(padding), i32(dilation),
                i32(Hout), i32(Wout), i32(Dout),
                i32(groups), i32(tile_h_in), i32(tile_w_in),
            ],
        )

        return y

