import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the (K, K, 1) 3D convolution.
#
# This is a direct (non-tiled) formulation of the same algorithm expressed by
# the CuTe/CUDA reference kernel: every thread computes one output element
# (n, oc, oh, ow, od) via a grid-stride loop, gathers the corresponding input
# window from global memory, accumulates against the corresponding weight
# slice, adds the optional bias, and writes the result. Group semantics,
# stride/padding/dilation handling and the (Kh, Kw, Kd=1) kernel shape all
# match the reference implementation exactly.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry conv3d_hw1_kernel(
    .param .u64 p_X,
    .param .u64 p_W,
    .param .u64 p_Bias,
    .param .u64 p_Y,
    .param .u32 p_N,
    .param .u32 p_Cin,
    .param .u32 p_H,
    .param .u32 p_Win,
    .param .u32 p_D,
    .param .u32 p_Cout,
    .param .u32 p_CinPerGroup,
    .param .u32 p_CoutPerGroup,
    .param .u32 p_Kh,
    .param .u32 p_Kw,
    .param .u32 p_Stride,
    .param .u32 p_Padding,
    .param .u32 p_Dilation,
    .param .u32 p_Hout,
    .param .u32 p_Wout,
    .param .u32 p_Dout,
    .param .u32 p_Total
)
{
    .reg .pred   %p<20>;
    .reg .b32    %r<60>;
    .reg .b64    %rd<90>;
    .reg .f32    %f<10>;

    ld.param.u64    %rd1, [p_X];
    ld.param.u64    %rd2, [p_W];
    ld.param.u64    %rd3, [p_Bias];
    ld.param.u64    %rd4, [p_Y];
    ld.param.u32    %r1,  [p_N];
    ld.param.u32    %r2,  [p_Cin];
    ld.param.u32    %r3,  [p_H];
    ld.param.u32    %r4,  [p_Win];
    ld.param.u32    %r5,  [p_D];
    ld.param.u32    %r6,  [p_Cout];
    ld.param.u32    %r7,  [p_CinPerGroup];
    ld.param.u32    %r8,  [p_CoutPerGroup];
    ld.param.u32    %r9,  [p_Kh];
    ld.param.u32    %r10, [p_Kw];
    ld.param.u32    %r11, [p_Stride];
    ld.param.u32    %r12, [p_Padding];
    ld.param.u32    %r13, [p_Dilation];
    ld.param.u32    %r14, [p_Hout];
    ld.param.u32    %r15, [p_Wout];
    ld.param.u32    %r16, [p_Dout];
    ld.param.u32    %r17, [p_Total];

    cvta.to.global.u64 %rd5, %rd1;
    cvta.to.global.u64 %rd6, %rd2;
    cvta.to.global.u64 %rd7, %rd4;

    mov.u32         %r20, %ctaid.x;
    mov.u32         %r21, %ntid.x;
    mov.u32         %r22, %tid.x;
    mad.lo.s32      %r23, %r20, %r21, %r22;
    mov.u32         %r24, %nctaid.x;
    mul.lo.s32      %r25, %r24, %r21;

LOOP_START:
    setp.ge.s32     %p1, %r23, %r17;
    @%p1 bra DONE;

    div.s32         %r30, %r23, %r16;
    rem.s32         %r31, %r23, %r16;
    div.s32         %r32, %r30, %r15;
    rem.s32         %r33, %r30, %r15;
    div.s32         %r34, %r32, %r14;
    rem.s32         %r35, %r32, %r14;
    div.s32         %r36, %r34, %r6;
    rem.s32         %r37, %r34, %r6;

    div.s32         %r38, %r37, %r8;

    mul.lo.s32      %r40, %r31, %r11;
    sub.s32         %r41, %r40, %r12;

    setp.lt.s32     %p2, %r41, 0;
    setp.ge.s32     %p3, %r41, %r5;
    or.pred         %p4, %p2, %p3;

    mov.f32         %f1, 0f00000000;

    @%p4 bra ADD_BIAS;

    mul.lo.s32      %r42, %r35, %r11;
    sub.s32         %r43, %r42, %r12;
    mul.lo.s32      %r44, %r33, %r11;
    sub.s32         %r45, %r44, %r12;

    mov.u32         %r50, 0;

C_LOOP:
    setp.ge.s32     %p5, %r50, %r7;
    @%p5 bra C_DONE;

    mad.lo.s32      %r51, %r38, %r7, %r50;

    mov.u32         %r52, 0;

KH_LOOP:
    setp.ge.s32     %p6, %r52, %r9;
    @%p6 bra KH_DONE;

    mul.lo.s32      %r53, %r52, %r13;
    add.s32         %r54, %r43, %r53;

    setp.lt.s32     %p7, %r54, 0;
    setp.ge.s32     %p8, %r54, %r3;
    or.pred         %p9, %p7, %p8;
    @%p9 bra KH_NEXT;

    mov.u32         %r55, 0;

KW_LOOP:
    setp.ge.s32     %p10, %r55, %r10;
    @%p10 bra KW_DONE;

    mul.lo.s32      %r56, %r55, %r13;
    add.s32         %r57, %r45, %r56;

    setp.lt.s32     %p11, %r57, 0;
    setp.ge.s32     %p12, %r57, %r4;
