        TILE = 16
        IH_TILE = (TILE - 1) * stride + (Kh - 1) * dilation + 1
        IW_TILE = (TILE - 1) * stride + (Kw - 1) * dilation + 1

        grid_x = max(1, (Wout + TILE - 1) // TILE)
        grid_y = max(1, (Hout + TILE - 1) // TILE)
        NDout = N * Dout
        grid_z = max(1, min(NDout, 65535))

