class ModelNew(nn.Module):
    """
    3D convolution with kernel (K, K, 1), implemented via a hand-written
    PTX kernel launched through cutegen.ptx_runtime.PtxModule.

    The kernel tiles the (Hout, Wout) output plane per CTA for a fixed
    (batch, group, output-depth) triple, stages the required haloed input
    window into shared memory once per CTA, and reuses it across all output
    channels of that group (register-resident accumulation), removing the
    redundant global-memory re-reads of X that a fully direct per-output
    thread mapping would otherwise incur.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        # Weight shape matches nn.Conv3d: [Cout, Cin/groups, Kh, Kw, Kd=1]
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 is supported"

        x_c = x.contiguous()
        w_c = self.weight.squeeze(-1).contiguous()  # [Cout, Cin/groups, Kh, Kw]

        N, Cin, H, Win, D = x_c.shape
        Cout, Cin_per_group, Kh, Kw = w_c.shape
        stride = int(self.stride)
        padding = int(self.padding)
        dilation = int(self.dilation)
        groups = int(self.groups)

        assert Cin % groups == 0 and Cout % groups == 0
        assert Cin_per_group == Cin // groups
        Cout_per_group = Cout // groups

        Hout = (H + 2 * padding - dilation * (Kh - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (Kw - 1) - 1) // stride + 1
        Dout = (D + 2 * padding - 1 * (1 - 1) - 1) // stride + 1  # kernel depth == 1

        assert Hout > 0 and Wout > 0 and Dout > 0

        y = torch.empty((N, Cout, Hout, Wout, Dout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            bias_ptr = int(b_c.data_ptr())
        else:
            b_c = None
            bias_ptr = 0

        tile_h_in = (_TILE_OH - 1) * stride + (Kh - 1) * dilation + 1
        tile_w_in = (_TILE_OW - 1) * stride + (Kw - 1) * dilation + 1

        grid_x = max(1, (Wout + _TILE_OW - 1) // _TILE_OW)
        grid_y = max(1, (Hout + _TILE_OH - 1) // _TILE_OH)
        grid_z = max(1, N * groups * Dout)

        shared_mem_bytes = int(Cin_per_group * tile_h_in * tile_w_in * 4)

        module = _get_module()
        stream = torch.cuda.current_stream(device=x.device).cuda_stream

        module.launch(
            _KERNEL_NAME,
            grid=(grid_x, grid_y, grid_z),
            block=(_TILE_OW, _TILE_OH, 1),
            shared_mem_bytes=shared_mem_bytes,
            stream=stream,
            args=[
                u64(int(x_c.data_ptr())),
                u64(int(w_c.data_ptr())),
                u64(bias_ptr),
                u64(int(y.data_ptr())),
                i32(N), i32(Cin), i32(H), i32(Win), i32(D),
                i32(Cout), i32(Cin_per_group), i32(Cout_per_group),
                i32(Kh), i32(Kw),
                i32(stride), i32(padding), i32(dilation),
                i32(Hout), i32(Wout), i32(Dout),
                i32(groups), i32(tile_h_in), i32(tile_w_in),
            ],
        )

        return y

